function duplicateObject(obj, count) {
  const n = Number(count) || 1;
  return Array.from({ length: n }, () => ({ ...obj }));
}

const incomingPrompt = $json;
const numberOfVariants = $('Initial Input').first().json.num_variants || 1;

console.log("incomingPrompt: ",incomingPrompt)

const output = duplicateObject(incomingPrompt, numberOfVariants);

return {output}
